//! The SDK generator: SDK drift from the Session API shows up as a CI diff. From the
//! [`Protocol`] table it renders the JSON Schema, the TypeScript client (`sdk/ts/src/*.ts`,
//! node ≥ 22.6 runs it with `--experimental-strip-types`), and the Python asyncio client
//! (`sdk/python/aho_sdk/*.py`, TypedDicts). Every file carries [`HEADER`];
//! `tests/drift.rs` fails when the committed files differ from a fresh render.

mod jsonschema;
mod python;
mod typescript;

use std::path::{Path, PathBuf};

use crate::protocol::Protocol;

/// First line of every generated file (as a comment, or `$comment` in the JSON Schema).
pub const HEADER: &str = "@generated by `cargo run -p aho-sdk -- gen` from crates/bundles/aho-sdk/src/protocol.rs. Do not edit.";

/// Directories (under the SDK root) that hold only generated files, plus hand-written ones
/// without the header; a file there with the header that the generator no longer renders is stale.
const GENERATED_DIRS: &[&str] = &["schema", "ts/src", "python/aho_sdk"];

/// One rendered file, `path` relative to the SDK root (`aho/sdk`).
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Generated {
    pub path: &'static str,
    pub text: String,
}

pub fn generate(p: &Protocol) -> Vec<Generated> {
    vec![
        Generated { path: "schema/aho-rpc.schema.json", text: jsonschema::render(p) },
        Generated { path: "ts/src/protocol.ts", text: typescript::protocol(p) },
        Generated { path: "ts/src/runtime.ts", text: typescript::runtime() },
        Generated { path: "ts/src/client.ts", text: typescript::client(p) },
        Generated { path: "ts/src/index.ts", text: typescript::index() },
        Generated { path: "python/aho_sdk/protocol.py", text: python::protocol(p) },
        Generated { path: "python/aho_sdk/runtime.py", text: python::runtime() },
        Generated { path: "python/aho_sdk/client.py", text: python::client(p) },
        Generated { path: "python/aho_sdk/__init__.py", text: python::init() },
    ]
}

/// `aho/sdk` in this checkout.
#[allow(clippy::disallowed_methods, reason = "authority: sdk-codegen-dir")]
pub fn default_dir() -> PathBuf {
    let dir = Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../sdk");
    std::fs::canonicalize(&dir).unwrap_or(dir)
}

/// Writes every file whose content changed; returns the paths written.
#[allow(clippy::disallowed_methods, reason = "authority: sdk-codegen-write")]
pub fn write(dir: &Path, files: &[Generated]) -> std::io::Result<Vec<PathBuf>> {
    let mut wrote = Vec::new();
    for f in files {
        let path = dir.join(f.path);
        if std::fs::read_to_string(&path).is_ok_and(|now| now == f.text) {
            continue;
        }
        if let Some(parent) = path.parent() {
            std::fs::create_dir_all(parent)?;
        }
        std::fs::write(&path, &f.text)?;
        wrote.push(path);
    }
    Ok(wrote)
}

/// Differences between `dir` and a fresh render: missing or edited files, and stale generated
/// files the generator no longer produces. Empty = in sync.
#[allow(clippy::disallowed_methods, reason = "authority: sdk-codegen-drift")]
pub fn drift(dir: &Path, files: &[Generated]) -> Vec<String> {
    let mut out = Vec::new();
    for f in files {
        match std::fs::read_to_string(dir.join(f.path)) {
            Ok(now) if now == f.text => {}
            Ok(_) => out.push(format!("{} differs from the protocol table", f.path)),
            Err(e) => out.push(format!("{} cannot be read ({e})", f.path)),
        }
    }
    for d in GENERATED_DIRS {
        let Ok(rd) = std::fs::read_dir(dir.join(d)) else { continue };
        let mut entries: Vec<std::fs::DirEntry> = rd.filter_map(Result::ok).collect();
        entries.sort_by_key(|e| e.file_name());
        for e in entries {
            let rel = format!("{d}/{}", e.file_name().to_string_lossy());
            let generated_here = std::fs::read_to_string(e.path()).is_ok_and(|t| t.contains(HEADER));
            if generated_here && !files.iter().any(|f| f.path == rel) {
                out.push(format!("{rel} is generated but no longer rendered; delete it"));
            }
        }
    }
    out
}

/// `tool_use_start` → `ToolUseStart`.
pub(crate) fn pascal(s: &str) -> String {
    s.split(['_', '.'])
        .map(|w| {
            let mut c = w.chars();
            c.next().map(|h| h.to_uppercase().chain(c).collect::<String>()).unwrap_or_default()
        })
        .collect()
}

/// `answer_approval` → `answerApproval`.
pub(crate) fn camel(s: &str) -> String {
    let p = pascal(s);
    let mut c = p.chars();
    c.next().map(|h| h.to_lowercase().chain(c).collect()).unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn names_convert_for_each_language() {
        assert_eq!(pascal("tool_use_start"), "ToolUseStart");
        assert_eq!(pascal("session_seen"), "SessionSeen");
        assert_eq!(camel("answer_approval"), "answerApproval");
        assert_eq!(camel("prompt"), "prompt");
    }

    #[test]
    fn drift_reports_edited_missing_and_stale_files() {
        let dir = tempfile::tempdir().unwrap();
        let files = vec![
            Generated { path: "ts/src/a.ts", text: format!("// {HEADER}\na\n") },
            Generated { path: "ts/src/b.ts", text: format!("// {HEADER}\nb\n") },
        ];
        write(dir.path(), &files).unwrap();
        assert!(drift(dir.path(), &files).is_empty());
        assert!(write(dir.path(), &files).unwrap().is_empty(), "unchanged files are not rewritten");
        std::fs::write(dir.path().join("ts/src/a.ts"), "edited").unwrap();
        std::fs::remove_file(dir.path().join("ts/src/b.ts")).unwrap();
        std::fs::write(dir.path().join("ts/src/old.ts"), format!("// {HEADER}\n")).unwrap();
        std::fs::write(dir.path().join("ts/src/handwritten.ts"), "export {};\n").unwrap();
        let d = drift(dir.path(), &files);
        assert_eq!(d.len(), 3, "{d:?}");
        assert!(d[0].starts_with("ts/src/a.ts differs"));
        assert!(d[1].starts_with("ts/src/b.ts cannot be read"));
        assert!(d[2].starts_with("ts/src/old.ts is generated but no longer rendered"));
    }
}
